    revive:       { simTargeting: 'tile',  simPhase: 'slow',     simFallback: null },
    manaRestoreAll:{ simTargeting: 'self', simPhase: 'standard', simFallback: null },
    remoteView:   { simTargeting: 'unit',  simPhase: 'fast',     simFallback: 'fizzle' },

