            Object.keys(RACE_ABILITIES).forEach(r => {
                const arr = RACE_ABILITIES[r];
                for (let i = arr.length - 1; i >= 0; i--) if (arr[i].id === id) arr.splice(i, 1);
            });
            delete SPELL_BY_ID[id];
            delete RACE_ABILITY_BY_ID[id];
